class TLCUDASourceWrapper(object):
    _TYPE_MAP = {
        "float32": "float",
        "float16": "half_t",
        "bfloat16": "bfloat16_t",
        "e4m3_float8": "fp8_e4_t",
        "e5m2_float8": "fp8_e5_t",
        "float64": "double",
